<?php if (!defined('ABSPATH')) exit; $options=woogit_theme_options(); $social=woogit_theme_items('social_links_json'); $enamad=woogit_enamad_settings(); $enamad_image=woogit_theme_image($options['enamad_image_id']??0,'medium'); ?></main><footer class="wg-footer"><div class="wg-container wg-footer__grid"><div><strong>WooGit</strong><p><?php echo woogit_safe_text($options['footer_text']??'مدیریت هوشمند فروشگاه ووکامرس.'); ?></p><?php if($enamad['enabled']): ?><div class="wg-enamad" aria-label="نماد اعتماد الکترونیکی"><?php if($enamad_image): ?><?php if($enamad['verification_url']): ?><a href="<?php echo esc_url($enamad['verification_url']); ?>" target="_blank" rel="noopener noreferrer"><img src="<?php echo esc_url($enamad_image); ?>" alt="<?php echo esc_attr($enamad['alt_text']?:'نماد اعتماد الکترونیکی'); ?>" loading="lazy" width="120" height="120"></a><?php else: ?><img src="<?php echo esc_url($enamad_image); ?>" alt="<?php echo esc_attr($enamad['alt_text']?:'نماد اعتماد الکترونیکی'); ?>" loading="lazy" width="120" height="120"><?php endif; ?><?php elseif($enamad['verification_url']): ?><a class="wg-badge" href="<?php echo esc_url($enamad['verification_url']); ?>" target="_blank" rel="noopener noreferrer">مشاهده نماد اعتماد</a><?php endif; ?></div><?php endif; ?></div><nav aria-label="ناوبری فوتر"><a href="<?php echo esc_url(woogit_page_url('privacy')); ?>">حریم خصوصی</a><a href="<?php echo esc_url(woogit_page_url('terms')); ?>">قوانین</a><a href="<?php echo esc_url(woogit_page_url('service-status')); ?>">وضعیت سرویس</a><a href="<?php echo esc_url(woogit_page_url('support')); ?>">پشتیبانی</a><?php if(!empty($options['support_email'])&&is_email($options['support_email'])):?><a href="<?php echo esc_url('mailto:'.$options['support_email']); ?>"><?php echo esc_html($options['support_email']); ?></a><?php endif; ?><?php foreach($social as $item){$url=isset($item['url'])?esc_url($item['url']):'';$label=isset($item['label'])?sanitize_text_field($item['label']):'';if($url&&$label)echo '<a href="'.esc_url($url).'" target="_blank" rel="noopener noreferrer">'.esc_html($label).'</a>';} ?></nav></div><div class="wg-container wg-footer__bottom"><span>© <?php echo esc_html(wp_date('Y')); ?> WooGit</span></div></footer><?php wp_footer(); ?></body></html>
